9	/**
10	 * Rejects a create request that shares another owner's household, i.e. has the same computed
11	 * {@code householdId} (last name and postcode, see {@link HouseholdId}). A request with
12	 * {@code sharesHousehold} true opts out and is created as a declared household member. Requests
13	 * without a postcode are not grouped into a household. A match rejects 409.
14	 */
15	public class RequireUniqueHousehold {
16	
17	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
18	            throws DuplicateOwnerHouseholdException {
19	        if (Boolean.TRUE.equals(request.getSharesHousehold())
20	                || request.getPostcode() == null || request.getPostcode().isBlank()) {
21	            return;
22	        }
23	        String household = HouseholdId.of(request.getLastName(), request.getPostcode());
24	        for (Owner owner : ownerRepository.findAll()) {
25	            if (household.equals(HouseholdId.of(owner.getLastName(), owner.getPostcode()))) {
26	                throw new DuplicateOwnerHouseholdException(owner.getLastName(), owner.getAddress());
27	            }
28	        }
29	    }
30	}
