9	/**
10	 * Rejects a create request whose lower-cased email is already used by any other owner. Runs after
11	 * {@link NormalizeOwnerEmail}, so the request email is already lower-cased; an absent email is
12	 * allowed. A match rejects 409.
13	 */
14	public class RequireUniqueOwnerEmail {
15	
16	    public void service(@Val OwnerFieldsDto request, OwnerRepository ownerRepository)
17	            throws DuplicateOwnerEmailException {
18	        String email = request.getEmail();
19	        if (email == null) {
20	            return;
21	        }
22	        for (Owner owner : ownerRepository.findAll()) {
23	            if (email.equalsIgnoreCase(owner.getEmail())) {
24	                throw new DuplicateOwnerEmailException(email);
25	            }
26	        }
27	    }
